style.css:
@-moz-document domain("roblox.com") {
html, body {
        background: url("https://i.postimg.cc/fWf7200h/4qfaaw3n.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Roblox often uses #container-main or #app as the wrapper */
    #container-main, #app, #rbx-body {
        background: transparent !important;
    }
}
